#include <stdint.h>
#ifdef CORE_MATH_SUPPORT_ERRNO
#include <errno.h>
#endif
#if defined(__x86_64__)
#include <x86intrin.h>
#else
#include <fenv.h> // for feraiseexcept, FE_UNDERFLOW
#endif

// Warning: clang also defines __GNUC__
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC diagnostic ignored "-Wunknown-pragmas"
#endif

/* __builtin_roundeven was introduced in gcc 10:
   https://gcc.gnu.org/gcc-10/changes.html,
   and in clang 17 */
#if ((defined(__GNUC__) && __GNUC__ >= 10) || (defined(__clang__) && __clang_major__ >= 17)) && !defined(_MSC_VER) && (defined(__aarch64__) || defined(__x86_64__) || defined(__i386__))
# define roundeven_finite(x) __builtin_roundeven (x)
#else
/* round x to nearest integer, breaking ties to even */
static double
roundeven_finite (double x)
{
  double ix;
# if (defined(__GNUC__) || defined(__clang__)) && (defined(__AVX__) || defined(__SSE4_1__) || (__ARM_ARCH >= 8))
#  if defined __AVX__
   __asm__("vroundsd $0x8,%1,%1,%0":"=x"(ix):"x"(x));
#  elif __ARM_ARCH >= 8
   __asm__ ("frintn %d0, %d1":"=w"(ix):"w"(x));
#  else /* __SSE4_1__ */
   __asm__("roundsd $0x8,%1,%0":"=x"(ix):"x"(x));
#  endif
# else
  ix = __builtin_round (x); /* nearest, away from 0 */
  if (__builtin_fabs (ix - x) == 0.5)
  {
    /* if ix is odd, we should return ix-1 if x>0, and ix+1 if x<0 */
    union { double f; uint64_t n; } u, v;
    u.f = ix;
    v.f = ix - __builtin_copysign (1.0, x);
    if (__builtin_ctz (v.n) > __builtin_ctz (u.n))
      ix = v.f;
  }
# endif
  return ix;
}
#endif

#pragma STDC FENV_ACCESS ON

typedef unsigned short ushort;
typedef uint64_t u64;
//typedef union {double f; uint64_t u;} b64u64_u; //already exists in erf
static inline double fasttwosum(double x, double y, double *e){
  double s = x + y, z = s - x;
  *e = y - z;
  return s;
}

static inline double fastsum(double xh, double xl, double yh, double yl, double *e){
  double sl, sh = fasttwosum(xh, yh, &sl);
  *e = (xl + yl) + sl;
  return sh;
}

static inline double sumdd(double xh, double xl, double yh, double yl, double *e){
  double sl, sh;
  if(__builtin_expect(__builtin_fabs(xh)>__builtin_fabs(yh), 1))
    sh = fasttwosum(xh, yh, &sl);
  else
    sh = fasttwosum(yh, xh, &sl);
  *e = (xl + yl) + sl;
  return sh;
}

static inline double twosum(double x, double y, double *e){
  if(__builtin_expect(__builtin_fabs(x)>__builtin_fabs(y), 1))
    return fasttwosum(x, y, e);
  else
    return fasttwosum(y, x, e);
}

static inline double muldd(double xh, double xl, double ch, double cl, double *l){
  double ahhh = ch*xh;
  *l = (ch*xl + cl*xh) + __builtin_fma(ch, xh, -ahhh);
  return ahhh;
}

static inline double muldd3(double xh, double xl, double yh, double yl, double *l){
  double ch = xh*yh, cl1 = __builtin_fma(xh,yh,-ch);
  double tl0 = xl*yl;
  double tl1 = tl0 + xh*yl;
  double cl2 = tl1 + xl*yh;
  double cl3 = cl1 + cl2;
  return fasttwosum(ch,cl3,l);
}

static inline double mulddd(double x, double ch, double cl, double *l){
  double ahhh = ch*x;
  *l = cl*x + __builtin_fma(ch, x, -ahhh);
  return ahhh;
}

static inline double polydd(double xh, double xl, int n, const double c[][2], double *l){
  int i = n-1;
  double cl, ch = fasttwosum(c[i][0], *l, &cl); cl += c[i][1];
  while(--i>=0){
    ch = muldd(xh,xl, ch,cl, &cl);
    ch = fastsum(c[i][0], c[i][1], ch, cl, &cl);
  }
  *l = cl;
  return ch;
}

/* Return ch+cl, a double-double approximation of
   c[0] + c[1]*x + ... + (c[n-1] + l)*x^(n-1)
   where each c[i] is a double-double number,
   with c[i][0] the upper part, and c[i][1] the lower part.
   cl is put in l at output (l is used both in input and output). */
static inline double polyddd(double x, int n, const double c[][2], double *l){
  int i = n-1;
  double cl, ch = fasttwosum(c[i][0], *l, &cl); cl += c[i][1];
  while(--i>=0){
    ch = mulddd(x, ch,cl, &cl);
    ch = sumdd(c[i][0],c[i][1], ch,cl, &cl);
  }
  *l = cl;
  return ch;
}

static inline double polyd(double x, int n, const double c[][2]){
  int i = n-1;
  double ch = c[i][0];
  while(--i>=0) ch = c[i][0] + x*ch;
  return ch;
}

static double __attribute__((noinline)) as_logd(double, double*);
static double __attribute__((noinline)) as_expd(double, double*, int*);
static double __attribute__((noinline)) as_sinpid(double, double*);
static double __attribute__((noinline)) as_lgamma_asym(double, double*);

// split x into xh+xl, where ulp(xh) = 2^-25
// if |x| <= 2^26, the splitting is exact
static inline double splt(double x, double *xl){
  static const double off = 0x1.8p27;
  double xh = (x + off) - off;
  *xl = x - xh;
  return xh;
}

// multiplies x by x0+x1+x2 where x1 <~ ulp(x0) and x2 <~ ulp(x1)
// and return the result as l0+l1+l2 where l0 is the return value
static inline double sprod(double x, double x0, double x1, double x2, double *l1, double *l2){
  double z0 = x*x0, z0l = __builtin_fma(x,x0,-z0), z1 = x*x1, z2 = x*x2 + __builtin_fma(x,x1,-z1), e;
  z0 = splt(z0, &e);
  e = fasttwosum(e, z0l, &z0l);
  *l1 = twosum(e, z1, &e);
  *l2 = e + z0l + z2;
  return z0;
}

static double poly3(double d, unsigned imax, const double ch[], unsigned jmax, const double cl[][2], double *ol){
  double t0 = 1, t1 = 0, t2 = 0;
  double s0 = ch[0], s1 = 0, s2 = 0;
  for(unsigned i=1;i<imax;i++){
    t0 = sprod(d, t0,t1,t2, &t1,&t2);
    s0 += t0*ch[i];
    double fl, fh = mulddd(ch[i], t1,t2, &fl);
    s1 = sumdd(s1,s2, fh,fl, &s2);
  }
  double fl = 0, fh = polyddd(d, jmax, cl, &fl);
  s1 = sumdd(s1,s2, fh,fl, &s2);
  s0 = fasttwosum(s0,s1, &s1);
  s1 = fasttwosum(s1,s2, &s2);
  *ol = s1;
  return s0;
}

