/*static inline double fasttwosum(double x, double y, double *e){ //all functions defined above
  double s = x + y, z = s - x;
  *e = y - z;
  return s;
}

static inline double twosum(double x, double y, double *e){
  if(__builtin_expect(__builtin_fabs(x)>__builtin_fabs(y), 1))
    return fasttwosum(x, y, e);
  else
    return fasttwosum(y, x, e);
}

static inline double fastsum(double xh, double xl, double yh, double yl, double *e){
  double sl, sh = fasttwosum(xh, yh, &sl);
  *e = (xl + yl) + sl;
  return sh;
}

static inline double sumdd(double xh, double xl, double yh, double yl, double *e){
  double sl, sh;
  char o = __builtin_fabs(xh)>__builtin_fabs(yh);
  if(__builtin_expect(o, 1))
    sh = fasttwosum(xh, yh, &sl);
  else
    sh = fasttwosum(yh, xh, &sl);
  sl += xl + yl;
  *e = sl;
  return sh;
}

static inline double muldd(double xh, double xl, double ch, double cl, double *l){
  double ahhh = ch*xh;
  *l = (ch*xl + cl*xh) + __builtin_fma(ch, xh, -ahhh);
  return ahhh;
}

static inline double mulddd(double x, double ch, double cl, double *l){
  double ahhh = ch*x;
  *l = cl*x + __builtin_fma(ch, x, -ahhh);
  return ahhh;
}

static inline double polydd(double xh, double xl, int n, const double c[][2], double *l){
  int i = n-1;
  double cl, ch = fasttwosum(c[i][0], *l, &cl); cl += c[i][1];
  while(--i>=0){
    ch = muldd(xh,xl, ch,cl, &cl);
    ch = fastsum(c[i][0], c[i][1], ch, cl, &cl);
  }
  *l = cl;
  return ch;
}*/

static inline double polydddfst(double x, int n, const double c[][2], double *l){
  int i = n-1;
  double cl, ch = fasttwosum(c[i][0], *l, &cl); cl += c[i][1];
  while(--i>=0){
    ch = mulddd(x, ch,cl, &cl);
    ch = fastsum(c[i][0],c[i][1], ch,cl, &cl);
  }
  *l = cl;
  return ch;
}

